import { DynamoDBClient, PutItemCommand, GetItemCommand } from '@aws-sdk/client-dynamodb';

const ddb = new DynamoDBClient({});
const TABLE = process.env.IDEMPOTENCY_TABLE!;

async function claimOrGet(key: string): Promise<'NEW' | 'DONE'> {
  try {
    await ddb.send(new PutItemCommand({
      TableName: TABLE,
      Item: { pk: { S: key }, status: { S: 'IN_PROGRESS' } },
      ConditionExpression: 'attribute_not_exists(pk)',
    }));
    return 'NEW';
  } catch (e: unknown) {
    if ((e as { name?: string }).name === 'ConditionalCheckFailedException') {
      const existing = await ddb.send(new GetItemCommand({ TableName: TABLE, Key: { pk: { S: key } } }));
      if (existing.Item?.status?.S === 'COMPLETED') return 'DONE';
      throw new Error('In progress by another worker');
    }
    throw e;
  }
}

async function handlePayment(event: { orderId: string; amount: number }) {
  const key = `charge:${event.orderId}`;
  const claim = await claimOrGet(key);
  if (claim === 'DONE') return; // already charged
  await stripeClient.charges.create({ amount: event.amount, idempotencyKey: key });
  await ddb.send(new UpdateItemCommand({
    TableName: TABLE,
    Key: { pk: { S: key } },
    UpdateExpression: 'SET status = :s',
    ExpressionAttributeValues: { ':s': { S: 'COMPLETED' } },
  }));
}
